function pinyinLine(text){
  if(lang!=='cmn'||!text)return '';
  const direct=pinyinGuide[text];
  const roman=direct||text.replace(/[\u3400-\u9fff]+/g,segment=>{
    const parts=[];
    for(let i=0;i<segment.length;){
      let length=Math.min(12,segment.length-i);
      while(length>1&&!pinyinGuide[segment.slice(i,i+length)])length--;
      const chunk=segment.slice(i,i+length);
      parts.push(pinyinGuide[chunk]||chunk);
      i+=length;
    }
    return parts.join(' ');
  });
  return roman&&roman!==text?'<p class="pinyin-line" lang="zh-Latn">'+clean(roman)+'</p>':'';
}
